class Solution {
public:
    int numberOfBoomerangs(vector<vector<int>>& points) {
        int total = 0;
        for (const auto& p : points) {
            unordered_map<int, int> distMap;
            for (const auto& q : points) {
                int dx = p[0] - q[0];
                int dy = p[1] - q[1];
                distMap[dx * dx + dy * dy]++;
            }
            for (const auto& pair : distMap) {
                total += pair.second * (pair.second - 1);
            }
        }
        return total;
    }
};

class Solution {
    public int numberOfBoomerangs(int[][] points) {
        int total = 0;
        for (int[] p : points) {
            Map<Integer, Integer> distMap = new HashMap<>();
            for (int[] q : points) {
                int dx = p[0] - q[0];
                int dy = p[1] - q[1];
                int d = dx * dx + dy * dy;
                distMap.put(d, distMap.getOrDefault(d, 0) + 1);
            }
            for (int cnt : distMap.values()) {
                total += cnt * (cnt - 1);
            }
        }
        return total;
    }
}

