var numberOfBoomerangs = function(points) {
    let total = 0;
    for (const p of points) {
        const distMap = new Map();
        for (const q of points) {
            const dx = p[0] - q[0];
            const dy = p[1] - q[1];
            const d = dx * dx + dy * dy;
            distMap.set(d, (distMap.get(d) || 0) + 1);
        }
        for (const cnt of distMap.values()) {
            total += cnt * (cnt - 1);
        }
    }
    return total;
};
